//! CLDR 48 list formatting.
//!
//! Patterns are generated by tools/unicode/format/generate_misc.py. Missing
//! parts are resolved through the CLDR style chain at generation time.

const std = @import("std");
const data = @import("list_data.zig");
const misc = @import("misc.zig");

pub const Style = enum {
    standard,
    standard_short,
    standard_narrow,
    or_,
    or_short,
    or_narrow,
    unit,
    unit_short,
    unit_narrow,
};

pub const Options = struct {
    style: Style = .standard,
};

pub const Error = error{OutOfMemory};

/// Format a list of strings with the locale's list patterns.
pub fn formatAlloc(
    allocator: std.mem.Allocator,
    items: []const []const u8,
    locale: []const u8,
    options: Options,
) Error![]u8 {
    if (items.len == 0) return allocator.dupe(u8, "");
    if (items.len == 1) return allocator.dupe(u8, items[0]);

    const locale_data = misc.findLocale(data.locales, locale) orelse
        misc.findLocale(data.locales, "en").?;
    const part = locale_data.patterns[@intFromEnum(options.style)];
    if (items.len == 2) {
        return formatPartAlloc(allocator, part.two, items[0], items[1]);
    }

    var current = try formatPartAlloc(
        allocator,
        part.start,
        items[0],
        items[1],
    );
    errdefer allocator.free(current);

    var index: usize = 2;
    while (index + 1 < items.len) : (index += 1) {
        const next = try formatPartAlloc(
            allocator,
            part.middle,
            current,
            items[index],
        );
        allocator.free(current);
        current = next;
    }

    const result = try formatPartAlloc(
        allocator,
        part.end,
        current,
        items[items.len - 1],
    );
    allocator.free(current);
    return result;
}

fn formatPartAlloc(
    allocator: std.mem.Allocator,
    pattern: []const u8,
    first: []const u8,
    second: []const u8,
) Error![]u8 {
    var output = std.ArrayList(u8).empty;
    errdefer output.deinit(allocator);
    var index: usize = 0;
    while (index < pattern.len) {
        if (pattern[index] == '{' and index + 2 < pattern.len and
            pattern[index + 2] == '}')
        {
            switch (pattern[index + 1]) {
                '0' => {
                    try output.appendSlice(allocator, first);
                    index += 3;
                    continue;
                },
                '1' => {
                    try output.appendSlice(allocator, second);
                    index += 3;
                    continue;
                },
                else => {},
            }
        }
        try output.append(allocator, pattern[index]);
        index += 1;
    }
    return output.toOwnedSlice(allocator);
}

test "list formatting" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;

    const items = [_][]const u8{ "a", "b", "c" };
    const english = try formatAlloc(allocator, &items, "en", .{});
    defer allocator.free(english);
    try testing.expectEqualStrings("a, b, and c", english);

    const pair = try formatAlloc(allocator, items[0..2], "en", .{});
    defer allocator.free(pair);
    try testing.expectEqualStrings("a and b", pair);

    const or_list = try formatAlloc(
        allocator,
        &items,
        "en",
        .{ .style = .or_ },
    );
    defer allocator.free(or_list);
    try testing.expectEqualStrings("a, b, or c", or_list);

    const french = try formatAlloc(allocator, &items, "fr", .{});
    defer allocator.free(french);
    try testing.expectEqualStrings("a, b et c", french);

    const arabic = try formatAlloc(allocator, &items, "ar", .{});
    defer allocator.free(arabic);
    try testing.expectEqualStrings("a \u{0648}b \u{0648}c", arabic);

    const japanese = try formatAlloc(allocator, &items, "ja", .{});
    defer allocator.free(japanese);
    try testing.expectEqualStrings("a\u{3001}b\u{3001}c", japanese);

    const chinese = try formatAlloc(allocator, &items, "zh", .{});
    defer allocator.free(chinese);
    try testing.expectEqualStrings("a\u{3001}b\u{548c}c", chinese);

    const single = try formatAlloc(allocator, items[0..1], "en", .{});
    defer allocator.free(single);
    try testing.expectEqualStrings("a", single);

    const empty = try formatAlloc(allocator, &.{}, "en", .{});
    defer allocator.free(empty);
    try testing.expectEqualStrings("", empty);

    const fallback = try formatAlloc(allocator, &items, "en-GB", .{});
    defer allocator.free(fallback);
    try testing.expectEqualStrings("a, b, and c", fallback);
}

test "list formatting covers additional locales" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;

    const items = [_][]const u8{ "a", "b", "c" };
    const cases = [_]struct { locale: []const u8, expected: []const u8 }{
        .{ .locale = "de", .expected = "a, b und c" },
        .{ .locale = "es", .expected = "a, b y c" },
        .{ .locale = "it", .expected = "a, b e c" },
        .{ .locale = "nl", .expected = "a, b en c" },
        .{ .locale = "pl", .expected = "a, b i c" },
        .{ .locale = "tr", .expected = "a, b ve c" },
        .{ .locale = "ko", .expected = "a, b \u{BC0F} c" },
        .{ .locale = "sv", .expected = "a, b och c" },
        .{ .locale = "da", .expected = "a, b og c" },
        .{ .locale = "fi", .expected = "a, b ja c" },
        .{ .locale = "cs", .expected = "a, b a\u{00A0}c" },
    };
    for (cases) |case| {
        const result = try formatAlloc(allocator, &items, case.locale, .{});
        defer allocator.free(result);
        try testing.expectEqualStrings(case.expected, result);
    }
}
